":130000,"meio":"boleto","ct":"Banco do Brasil","o":null}]}$json$::jsonb;
begin
  select count(*) into v_n from perfis;
  if v_n <> 1 then raise exception 'Esperava 1 perfil, encontrei %', v_n; end if;
  select id into v_owner from perfis;

  select id into v_cartao from cartoes
   where owner_id = v_owner and apelido ilike '%nubank%' and not arquivado
   order by criado_em limit 1;
  if v_cartao is null then raise exception 'Cartão Nubank não encontrado'; end if;

  if exists (select 1 from compras where owner_id = v_owner and id_externo like 'imp2026:%') then
    raise notice 'Importação já aplicada antes — nada foi alterado.';
    return;
  end if;

  -- Compras já lançadas no app que este arquivo NÃO reimporta (pelo ID de cada uma).
  update compras set id_externo = 'manual:' || id
   where owner_id = v_owner and id_externo is null and id in (
     'aa373f4c-0d62-4dc2-9ac2-2a9941708d38',   -- Empréstimo Ágata
     '012e97b6-a682-4371-93a5-7440ef57b710',   -- Feira
     '11615b3f-fd63-401f-9da5-9423d97f65be',   -- Mêsversario Ágata Setembro (2)
     '82005e0b-e9fe-468e-9b93-545a64f68e8e',   -- Big box
     '4a4d1d5c-10bd-42b2-a38d-300aabc0c737',   -- Super Adega
     '5184565f-5611-42fe-9099-86290468895b');  -- Compras 18/10

  -- Estas 4 substituem linhas do extrato; sem elas as faturas de out e nov ficam incompletas.
  select count(*) into v_n from compras where owner_id = v_owner and id in (
     '012e97b6-a682-4371-93a5-7440ef57b710', '11615b3f-fd63-401f-9da5-9423d97f65be',
     '82005e0b-e9fe-468e-9b93-545a64f68e8e', '4a4d1d5c-10bd-42b2-a38d-300aabc0c737');
  if v_n <> 4 then
    raise exception 'Esperava as 4 compras do mercado já lançadas (Feira, Mêsversario, Big box, Super Adega) e achei %. Não apague essas compras antes de importar.', v_n;
  end if;

  select count(*) into v_n from compras
   where owner_id = v_owner and id_externo is null and data_compra >= '2025-12-05';
  if v_n > 0 then
    raise exception 'Há % compra(s) nova(s) lançada(s) à mão depois da exportação de 19/10. Para não duplicar, me mande a lista (consulta no GUIA) antes de importar.', v_n;
  end if;

  select id into v_outros from categorias where owner_id = v_owner and lower(btrim(nome)) = 'outros' limit 1;
  if v_outros is null then raise exception 'Categoria "Outros" não encontrada'; end if;

  -- Faturas: fecha dia 5, vence dia 12 (mês de referência = mês do vencimento).
  insert into faturas (owner_id, cartao_id, mes_referencia, data_fechamento, data_vencimento)
  select v_owner, v_cartao, (m.mes || '-01')::date, (m.mes || '-05')::date, (m.mes || '-12')::date
    from jsonb_array_elements_text(v_dados->'faturas') as m(mes)
  on conflict (cartao_id, mes_referencia) do nothing;

  insert into compras (owner_id, descricao, data_compra, valor_total_centavos, categoria_id,
                       forma_pagamento, cartao_id, parcelas, origem, estabelecimento,
                       observacoes, conta_origem, id_externo)
  select v_owner, x.d, x.dt, x.v, coalesce(c.id, v_outros), x.f::forma_pagamento,
         case when x.f = 'credito' then v_cartao end, x.p, 'importacao', x.es, x.o, x.ct, x.e
    from jsonb_to_recordset(v_dados->'compras')
         as x(e text, d text, dt date, v bigint, cat text, f text, p smallint, o text, ct text, es text)
    left join categorias c on c.owner_id = v_owner and lower(btrim(c.nome)) = lower(x.cat);

  insert into lancamentos_mensais (owner_id, compra_id, categoria_id, valor_centavos,
                                   mes_competencia, numero_parcela, total_parcelas, fatura_id)
  select v_owner, cp.id, cp.categoria_id, l.v,
         coalesce(f.mes_referencia, (l.mes || '-01')::date), l.n, l.t, f.id
    from jsonb_to_recordset(v_dados->'lanc') as l(e text, n smallint, t smallint, v bigint, fat text, mes text)
    join compras cp on cp.owner_id = v_owner and cp.id_externo = l.e
    left join faturas f on f.cartao_id = v_cartao and l.fat is not null
                       and f.mes_referencia = (l.fat || '-01')::date;

  insert into ajustes_fatura (owner_id, fatura_id, valor_centavos, tipo, descricao, id_externo)
  select v_owner, f.id, a.v, a.tipo, a.d, a.e
    from jsonb_to_recordset(v_dados->'ajustes') as a(e text, fat text, v bigint, tipo text, d text)
    join faturas f on f.cartao_id = v_cartao and f.mes_referencia = (a.fat || '-01')::date;

  insert into pagamentos_fatura (owner_id, fatura_id, data, valor_centavos, meio,
                                 conta_origem, observacao, id_externo)
  select v_owner, f.id, p.dt, p.v, p.meio::meio_pagamento_fatura, p.ct, p.o, p.e
    from jsonb_to_recordset(v_dados->'pagamentos') as p(e text, fat text, dt date, v bigint, meio text, ct text, o text)
    join faturas f on f.cartao_id = v_cartao and f.mes_referencia = (p.fat || '-01')::date;

  select count(*) into v_n from compras where owner_id = v_owner and id_externo like 'imp2026:%';
  raise notice 'Importação concluída: % compras.', v_n;
end
$imp$;

